// ô ~190pt — ảnh gốc 2000×2000
GridView.builder(
  itemCount: 120,
  itemBuilder: (context, i) {
    return Image.asset(
      _assetPath(i),
      // decode đúng cỡ hiển thị @2x
      cacheWidth: 380,
      fit: BoxFit.cover,
    );
  },
)
// bitmap = w × h × 4 byte
// 2000px 15.26MB → 380px 0.55MB
